:root{--bg:#f4f1ea;--fg:#1d2a2f;--card:#fff;--bd:#c9c3b5;--ac:#1f7a8c}
@media(prefers-color-scheme:dark){:root{--bg:#14201f;--fg:#e6ece8;--card:#1d2e2d;--bd:#365250;--ac:#3fb0c4}}
body{background:var(--bg);color:var(--fg);font:15px system-ui,sans-serif;margin:0 auto;padding:10px;max-width:860px}
h1{font-size:20px;margin:4px 0 8px}
.row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px}
label{display:flex;flex-direction:column;font-size:12px;gap:2px;flex:1;min-width:110px}
select{padding:7px;border-radius:8px;border:1px solid var(--bd);background:var(--card);color:var(--fg);font-size:14px}
select:disabled{opacity:.5}
.wrap{position:relative}
canvas{width:100%;display:block;border-radius:12px;border:1px solid var(--bd);touch-action:none}
#btn{width:100%;padding:16px;font-size:18px;border:0;border-radius:12px;background:var(--ac);color:#fff;margin-top:8px;user-select:none;-webkit-user-select:none;touch-action:none}
#msg{min-height:22px;margin:8px 0 2px;font-weight:600}
#stat{font-size:13px;opacity:.8}
#hist{width:100%;font-size:13px;margin-top:8px;border-collapse:collapse}
#hist td{padding:3px 6px;border-bottom:1px solid var(--bd)}
#card{position:absolute;inset:0;display:none;align-items:center;justify-content:center;background:rgba(0,0,0,.45);border-radius:12px}
#card>div{background:var(--card);border:1px solid var(--bd);border-radius:14px;padding:18px;text-align:center;min-width:220px}
#card .small{font-size:13px}#card .big{font-size:22px;font-weight:700;margin:6px 0}#cw{font-size:18px}
#card button{padding:10px 16px;margin:6px 4px 0;border-radius:10px;border:1px solid var(--bd);background:var(--ac);color:#fff;font-size:15px}
#card button.o{background:var(--card);color:var(--fg)}
.top{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.top h1{margin:0}.sp{flex:1}.money{font-weight:700}
button{padding:7px 12px;border-radius:9px;border:1px solid var(--bd);background:var(--ac);color:#fff;font-size:14px}
button.o{background:var(--card);color:var(--fg)}
button:disabled{opacity:.5}
#tut{display:none;margin:8px 0;padding:10px 12px;border-radius:10px;background:#f2b632;color:#2a2200;gap:10px;align-items:center;justify-content:space-between;flex-wrap:wrap}
#tut button{margin-left:6px}
.hl{outline:3px solid #f2b632;outline-offset:3px;border-radius:12px;animation:pl 1s infinite alternate}
@keyframes pl{to{outline-color:transparent}}
.modal{position:fixed;inset:0;background:rgba(0,0,0,.5);display:none;align-items:center;justify-content:center;padding:12px;z-index:5}
.mb{background:var(--card);color:var(--fg);border:1px solid var(--bd);border-radius:14px;padding:16px;max-width:520px;width:100%;max-height:85vh;overflow:auto}
.mb h2{margin:0 0 10px;font-size:18px}.mb h3{margin:12px 0 4px;font-size:14px}
.mb table{width:100%;border-collapse:collapse;font-size:14px}.mb td,.mb th{padding:5px 4px;border-bottom:1px solid var(--bd);text-align:left}
#shopmsg{min-height:20px;color:#d9534f;font-size:13px;margin:6px 0}
.small{font-size:13px}.fl{font-size:12px;opacity:.75}

